-        final ElliottPhase currentPhase = switch (phase) {
-        case 2 -> ElliottPhase.WAVE2;
-        case 3 -> ElliottPhase.WAVE3;
-        case 4 -> ElliottPhase.WAVE4;
-        case 5 -> ElliottPhase.WAVE5;
